const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
console.log('Sheets:', wb.SheetNames);
wb.SheetNames.forEach(name => {
  const data = XLSX.utils.sheet_to_json(wb.Sheets[name]);
  console.log('\n--- ' + name + ' (' + data.length + ' rows) ---');
  // Print headers
  if (data.length > 0) console.log('Columns:', Object.keys(data[0]));
  // Print first 3 rows
  data.slice(0, 3).forEach(r => console.log(r));
});
"

cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

const filtered = data.filter(r => r.Customer === 'Maya Chen' && r.Date === '2026-09-02' && (r.Status === 'cancelled' || r.Status === 'confirmed'));

const cancelled = filtered.filter(r => r.Status === 'cancelled');
const confirmed = filtered.filter(r => r.Status === 'confirmed');

console.log('=== CANCELLED ORDERS (' + cancelled.length + ') ===');
cancelled.forEach(r => console.log(JSON.stringify(r)));

console.log('\n=== CONFIRMED ORDERS (' + confirmed.length + ') ===');
confirmed.forEach(r => console.log(JSON.stringify(r)));
"

